use serde::Serialize;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};

#[derive(Clone, Default)]
pub struct Metrics {
    inner: Arc<Inner>,
}

#[derive(Default)]
struct Inner {
    requests: AtomicU64,
    authentication_failures: AtomicU64,
    state_reads: AtomicU64,
    state_mutations: AtomicU64,
    event_connections: AtomicU64,
    sync_operations_sent: AtomicU64,
    sync_operations_received: AtomicU64,
    peer_sync_successes: AtomicU64,
    peer_sync_failures: AtomicU64,
    operations_compacted: AtomicU64,
    requests_shed: AtomicU64,
    request_deadlines_exceeded: AtomicU64,
}

#[derive(Serialize)]
pub struct MetricsSnapshot {
    pub requests: u64,
    pub authentication_failures: u64,
    pub state_reads: u64,
    pub state_mutations: u64,
    pub event_connections: u64,
    pub sync_operations_sent: u64,
    pub sync_operations_received: u64,
    pub peer_sync_successes: u64,
    pub peer_sync_failures: u64,
    pub operations_compacted: u64,
    /// Requests refused at the door because the server was already at its
    /// in-flight limit. Non-zero means load is being shed rather than queued.
    pub requests_shed: u64,
    /// Requests the server abandoned for exceeding its own deadline. Non-zero
    /// means scoped operations are stalling, whatever `/health` says.
    pub request_deadlines_exceeded: u64,
}

impl Metrics {
    pub fn request(&self) {
        self.inner.requests.fetch_add(1, Ordering::Relaxed);
    }
    pub fn authentication_failure(&self) {
        self.inner
            .authentication_failures
            .fetch_add(1, Ordering::Relaxed);
    }
    pub fn state_read(&self) {
        self.inner.state_reads.fetch_add(1, Ordering::Relaxed);
    }
    pub fn state_mutation(&self) {
        self.inner.state_mutations.fetch_add(1, Ordering::Relaxed);
    }
    pub fn event_connection(&self) {
        self.inner.event_connections.fetch_add(1, Ordering::Relaxed);
    }
    pub fn sync_sent(&self, count: u64) {
        self.inner
            .sync_operations_sent
            .fetch_add(count, Ordering::Relaxed);
    }
    pub fn sync_received(&self, count: u64) {
        self.inner
            .sync_operations_received
            .fetch_add(count, Ordering::Relaxed);
    }
    pub fn request_shed(&self) {
        self.inner.requests_shed.fetch_add(1, Ordering::Relaxed);
    }
    pub fn request_deadline_exceeded(&self) {
        self.inner
            .request_deadlines_exceeded
            .fetch_add(1, Ordering::Relaxed);
    }
    pub fn peer_sync_success(&self) {
        self.inner
            .peer_sync_successes
            .fetch_add(1, Ordering::Relaxed);
    }
    pub fn peer_sync_failure(&self) {
        self.inner
            .peer_sync_failures
            .fetch_add(1, Ordering::Relaxed);
    }
    pub fn operations_compacted(&self, count: u64) {
        self.inner
            .operations_compacted
            .fetch_add(count, Ordering::Relaxed);
    }
    pub fn snapshot(&self) -> MetricsSnapshot {
        MetricsSnapshot {
            requests: self.inner.requests.load(Ordering::Relaxed),
            authentication_failures: self.inner.authentication_failures.load(Ordering::Relaxed),
            state_reads: self.inner.state_reads.load(Ordering::Relaxed),
            state_mutations: self.inner.state_mutations.load(Ordering::Relaxed),
            event_connections: self.inner.event_connections.load(Ordering::Relaxed),
            sync_operations_sent: self.inner.sync_operations_sent.load(Ordering::Relaxed),
            sync_operations_received: self.inner.sync_operations_received.load(Ordering::Relaxed),
            peer_sync_successes: self.inner.peer_sync_successes.load(Ordering::Relaxed),
            peer_sync_failures: self.inner.peer_sync_failures.load(Ordering::Relaxed),
            operations_compacted: self.inner.operations_compacted.load(Ordering::Relaxed),
            requests_shed: self.inner.requests_shed.load(Ordering::Relaxed),
            request_deadlines_exceeded: self
                .inner
                .request_deadlines_exceeded
                .load(Ordering::Relaxed),
        }
    }
}
